function ParticlePortrait({ columns = 140, radius = 70, strength = 2.2, className = "" }) {
  const stageRef = useRef(null);
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const stage = stageRef.current;
    if (!canvas || !stage) return;
    const ctx = canvas.getContext("2d");
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    let raf = 0, dead = false, visible = true, s = null, mx = -1e5, my = -1e5;
    const img = new Image();

    const layout = () => {
      if (!s) return;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      s.dpr = dpr;
      s.W = Math.max(1, Math.floor(stage.clientWidth * dpr));
      s.H = Math.max(1, Math.floor(stage.clientHeight * dpr));
      canvas.width = s.W;
      canvas.height = s.H;
      s.image = ctx.createImageData(s.W, s.H);
      s.buf = new Uint32Array(s.image.data.buffer);
      
      const dh = Math.min(s.H, s.W / s.aspect);
      const dw = dh * s.aspect;
      const ox = (s.W - dw) / 2;
      const oy = s.H - dh;
      s.size = Math.max(1, Math.ceil(dw / columns));
      for (let i = 0; i < s.n; i++) {
        s.hx[i] = ox + s.nx[i] * dw - s.size / 2;
        s.hy[i] = oy + s.ny[i] * dh - s.size / 2;
      }
    };

    const build = () => {
      const rows = Math.round((columns * img.height) / img.width);
      const off = document.createElement("canvas");
      off.width = columns;
      off.height = rows;
      const octx = off.getContext("2d", { willReadFrequently: true });
      octx.drawImage(img, 0, 0, columns, rows);
      const px = octx.getImageData(0, 0, columns, rows).data;
      const keep = [];
      for (let i = 0; i < columns * rows; i++) if (px[i * 4 + 3] > 110) keep.push(i);
      const n = keep.length;
      s = {
        n, W: 1, H: 1, dpr: 1, size: 2, aspect: img.width / img.height,
        nx: new Float32Array(n), ny: new Float32Array(n),
        hx: new Float32Array(n), hy: new Float32Array(n),
        x: new Float32Array(n), y: new Float32Array(n),
        vx: new Float32Array(n), vy: new Float32Array(n),
        k: new Float32Array(n), color: new Uint32Array(n),
        image: null, buf: null,
      };
      keep.forEach((p, j) => {
        s.nx[j] = ((p % columns) + 0.5) / columns;
        s.ny[j] = (Math.floor(p / columns) + 0.5) / rows;
        s.color[j] = (255 << 24) | (px[p * 4 + 2] << 16) | (px[p * 4 + 1] << 8) | px[p * 4];
        s.k[j] = 0.012 + Math.random() * 0.03; /* har particle apni speed se settle hota hai */
      });
      layout();
      for (let i = 0; i < n; i++) {
        s.x[i] = reduce ? s.hx[i] : Math.random() * s.W;
        s.y[i] = reduce ? s.hy[i] : Math.random() * s.H;
      }
    };

    const frame = () => {
      if (!visible) { raf = 0; return; }
      if (s) {
        const { n, W, H, size, x, y, vx, vy, hx, hy, k, color, buf } = s;
        const R = radius * s.dpr, R2 = R * R, P = strength * s.dpr;
        buf.fill(0);
        for (let i = 0; i < n; i++) {
          let ax = (hx[i] - x[i]) * k[i];
          let ay = (hy[i] - y[i]) * k[i];
          const dx = x[i] - mx, dy = y[i] - my, d2 = dx * dx + dy * dy;
          if (d2 < R2 && d2 > 0.01) {
            const d = Math.sqrt(d2), f = (1 - d / R) * P;
            ax += (dx / d) * f;
            ay += (dy / d) * f;
          }
          vx[i] = (vx[i] + ax) * 0.88;
          vy[i] = (vy[i] + ay) * 0.88;
          x[i] += vx[i];
          y[i] += vy[i];
          const px = x[i] | 0, py = y[i] | 0;
          if (px < 0 || py < 0 || px + size > W || py + size > H) continue;
          const c = color[i];
          for (let b = 0; b < size; b++) {
            const row = (py + b) * W + px;
            for (let a = 0; a < size; a++) buf[row + a] = c;
          }
        }
        ctx.putImageData(s.image, 0, 0);
      }
      raf = requestAnimationFrame(frame);
    };

    img.onload = () => { if (!dead) { build(); raf = requestAnimationFrame(frame); } };
    img.src = PORTRAIT;

    const ro = new ResizeObserver(() => s && layout());
    ro.observe(stage);

    
    const io = new IntersectionObserver(([e]) => {
      visible = e.isIntersecting;
      if (visible && !raf && s) raf = requestAnimationFrame(frame);
    });
    io.observe(stage);

    const move = (e) => {
      if (!s) return;
      const r = canvas.getBoundingClientRect();
      mx = (e.clientX - r.left) * s.dpr;
      my = (e.clientY - r.top) * s.dpr;
    };
    const leave = () => { mx = my = -1e5; };
    if (!reduce) {
      window.addEventListener("pointermove", move, { passive: true });
      document.documentElement.addEventListener("pointerleave", leave);
    }

    return () => {
      dead = true;
      cancelAnimationFrame(raf);
      ro.disconnect();
      io.disconnect();
      window.removeEventListener("pointermove", move);
      document.documentElement.removeEventListener("pointerleave", leave);
    };
  }, [columns, radius, strength]);

  return (
    <div className={"jr-portrait " + className} ref={stageRef}>
      <canvas ref={canvasRef} role="img" aria-label="Portrait made of moving particles" />
    </div>
  );
}


function MoveText({ text, radius = 150, power = 0.32, scale = 0.22 }) {
  const ref = useRef(null);

  useEffect(() => {
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const root = ref.current;
    if (!root) return;
    let raf = 0;

    const letters = () => root.querySelectorAll("[data-c]");
    const reset = () =>
      letters().forEach((el) => {
        el.style.transform = "";
        el.style.setProperty("--t", "0");
      });

    const onMove = (e) => {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => {
        const rr = root.getBoundingClientRect();
        const far =
          e.clientY < rr.top - radius ||
          e.clientY > rr.bottom + radius ||
          e.clientX < rr.left - radius ||
          e.clientX > rr.right + radius;
        if (far) return reset();

        letters().forEach((el) => {
          /* offsetLeft/Top ignore transforms, so letters never jitter */
          const cx = rr.left + el.offsetLeft + el.offsetWidth / 2;
          const cy = rr.top + el.offsetTop + el.offsetHeight / 2;
          const dx = cx - e.clientX;
          const dy = cy - e.clientY;
          const d = Math.hypot(dx, dy) || 1;
          if (d > radius) {
            el.style.transform = "";
            el.style.setProperty("--t", "0");
            return;
          }
          const t = Math.pow(1 - d / radius, 2);
          const push = t * radius * power;
          el.style.transform = `translate(${(dx / d) * push}px, ${(dy / d) * push}px) scale(${1 + t * scale})`;
          el.style.setProperty("--t", t.toFixed(3));
        });
      });
    };

    const onLeave = () => reset();
    window.addEventListener("pointermove", onMove, { passive: true });
    document.documentElement.addEventListener("pointerleave", onLeave);
    return () => {
      window.removeEventListener("pointermove", onMove);
      document.documentElement.removeEventListener("pointerleave", onLeave);
      cancelAnimationFrame(raf);
    };
  }, [radius, power, scale]);

  return (
    <span className="mt" ref={ref} aria-label={text}>
      <span aria-hidden="true">
        {text.split(" ").map((word, wi, arr) => (
          <span className="mt-w" key={wi}>
            {[...word].map((ch, ci) => (
              <span className="mt-c" data-c key={ci}>
                {ch}
              </span>
            ))}
            {wi < arr.length - 1 ? " " : ""}
          </span>
        ))}
      </span>
    </span>
  );
}

function TechCard({ id, width = 280 }) {
  const t = TECH[id];
  return (
    <div className="jr-card" style={{ width }}>
      <div className="jr-card-bar" style={{ background: t.color }}>
        <i /><i /><i />
        <span>{t.label}</span>
      </div>
      <pre>
        {t.lines.map((l, i) => (
          <div key={i}>
            <b>{i + 1}</b>
            {l}
          </div>
        ))}
      </pre>
    </div>
  );
}


function TypedCard({ id }) {
  const t = TECH[id];
  const full = t.lines.join("\n");
  const [n, setN] = useState(0);

  useEffect(() => {
    setN(0);
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) { setN(full.length); return; }
    const timer = setInterval(() => {
      setN((v) => (v >= full.length ? (clearInterval(timer), v) : v + 1));
    }, 20);
    return () => clearInterval(timer);
  }, [id, full]);

  const shown = full.slice(0, n).split("\n");
  return (
    <div className="jr-big-card" style={{ "--c": t.color }}>
      <div className="jr-card-bar" style={{ background: t.color }}>
        <i /><i /><i />
        <span>{t.label}</span>
      </div>
      <pre>
        {shown.map((l, i) => (
          <div key={i}>
            <b>{i + 1}</b>
            {l}
            {i === shown.length - 1 && <em className="jr-caret" />}
          </div>
        ))}
      </pre>
    </div>
  );
}

export default function Journey() {
  const [current, setCurrent] = useState(0);
  const barRef = useRef(null);

  
  useEffect(() => {
    let raf = 0;
    const onScroll = () => {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => {
        const y = window.scrollY;
        const max = document.documentElement.scrollHeight - window.innerHeight;
        if (barRef.current) barRef.current.style.transform = `scaleX(${max > 0 ? y / max : 0})`;
      });
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => { window.removeEventListener("scroll", onScroll); cancelAnimationFrame(raf); };
  }, []);

  const n = STEPS.length;
  const step = STEPS[current];
  const prev = STEPS[(current + n - 1) % n];
  const next = STEPS[(current + 1) % n];
  const marquee = STEPS.map((s) => s.tech);

  return (
    <div className="jr">
      <style>{css}</style>

      <div className="jr-progress"><div ref={barRef} /></div>

      
      <header className="jr-hero" id="top">
        <div className="jr-rule" />
        <ParticlePortrait className="top" />
        <div className="jr-small">
          {ROLE}<br />Learning in public
        </div>
        <h1>
          <span className="ln l1"><i><MoveText text={NAME} radius={120} /></i></span>
          <span className="ln l2"><i><MoveText text="From C and" /></i></span>
          <span className="ln l3"><i><MoveText text="C++ to the" /></i></span>
          <span className="ln l4"><i><MoveText text="full stack." /></i></span>
        </h1>
        <p className="jr-intro">
          Started in college with C, C++, Python and DSA. Moved to the web with HTML, CSS and
          JavaScript. Now heading to React, Three.js, Node.js and MongoDB.
        </p>
        <div className="jr-hint">Move your cursor over the headline.</div>
      </header>

     
      <div className="jr-marquee" aria-hidden="true">
        <div>
          {[...marquee, ...marquee].map((m, i) => (
            <span key={i}>{m}</span>
          ))}
        </div>
      </div>

      
      <section className="jr-path" id="path">
        <div className="jr-table-wrap">
          <h2><MoveText text="The path," /><br /><MoveText text="step by step." /></h2>

          <div className="jr-table" role="list">
            <div className="jr-row jr-head" aria-hidden="true">
              <span>No.</span><span>Technology</span><span>Stage</span><span>Status</span>
            </div>
            {STEPS.map((s, i) => (
              <div
                key={s.id}
                role="listitem"
                tabIndex={0}
                className={`jr-item${i === current ? " on" : ""}`}
                onMouseEnter={() => setCurrent(i)}
                onFocus={() => setCurrent(i)}
                onClick={() => setCurrent(i)}
              >
                <div className="jr-row">
                  <span>{String(i + 1).padStart(2, "0")}</span>
                  <span className="jr-tech"><MoveText text={s.tech} radius={90} power={0.22} scale={0.12} /></span>
                  <span>{s.stage}</span>
                  <span className={`jr-chip ${s.status === "Done" ? "done" : ""}`}>{s.status}</span>
                </div>
                <div className="jr-more">
                  <div>
                    <p>{s.note}</p>
                    <div className="jr-inline"><TechCard id={s.id} width={300} /></div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        <aside className="jr-show" aria-hidden="true">
          <div className="jr-glow" key={"g" + step.id} style={{ "--c": TECH[step.id].color }} />
          <div className="jr-scene">
            <div className="jr-ghost g1" key={"a" + prev.id}><TechCard id={prev.id} width={340} /></div>
            <div className="jr-ghost g2" key={"b" + next.id}><TechCard id={next.id} width={340} /></div>
            <div className="jr-front" key={step.id}><TypedCard id={step.id} /></div>
          </div>
          <div className="jr-info" key={"i" + step.id}>
            <div className="jr-count">
              <b>{String(current + 1).padStart(2, "0")}</b><span>/ {String(n).padStart(2, "0")}</span>
            </div>
            <div className="jr-tags">
              {TAGS[step.id].map((t) => <span key={t}>{t}</span>)}
            </div>
          </div>
        </aside>
      </section>

      
      <section className="jr-last" id="next">
        <div className="jr-rule" />
        <h2><MoveText text="Then the" /><br /><MoveText text="whole app." /></h2>
        <p className="jr-intro">
          React for the interface, Three.js for 3D, Node.js and MongoDB for the server and the data.
          That is a complete project, from the first button to the last database row.
        </p>
        <ParticlePortrait className="bottom" />
      </section>
    </div>
  );
}

const css = `
@import url("https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,500;12..96,700;12..96,800&family=DM+Sans:wght@400;500;700&display=swap");

/* background transparent -> poora page (.App ka --page-bg gradient) wahi dikhega
   jaise main file me, aur sticky glass nav ka color bhi bilkul same rahe */
.jr{--ink:#14161f;--paper:#f4f5f8;--mute:#7b8090;--line:#dadce4;--accent:#3a3af0;position:relative;background:transparent;color:var(--ink);
  font-family:"DM Sans","Helvetica Neue",Helvetica,Arial,sans-serif;overflow-x:clip}
.jr *{box-sizing:border-box}
.jr button{font:inherit;cursor:pointer}
.jr :focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.jr h1,.jr h2,.jr h3{margin:0;font-family:"Bricolage Grotesque","Helvetica Neue",Arial,sans-serif;font-weight:800;letter-spacing:-.045em;line-height:.95}
.jr-rule{position:absolute;top:0;bottom:0;left:calc(8vw + 18vw);width:1px;background:var(--ink);opacity:.9}
.jr-small{font-size:13px;line-height:1.35;font-weight:500;color:var(--mute)}
.jr-intro{font-size:16px;line-height:1.6;max-width:420px;margin:0;color:#3a3e4d}

/* ---- MoveText: letters that react to the cursor ---- */
.mt{position:relative;display:inline-block}
.mt-w{display:inline-block;white-space:nowrap}
.mt-c{display:inline-block;--t:0;will-change:transform;
  color:color-mix(in srgb,var(--accent) calc(var(--t) * 100%),currentColor);
  transition:transform .28s cubic-bezier(.2,.8,.2,1),color .28s ease-out}
@media (prefers-reduced-motion:reduce){.mt-c{transition:none}}

.jr-progress{position:fixed;top:0;left:0;right:0;height:3px;z-index:40}
.jr-progress div{height:100%;background:var(--accent);transform-origin:0 50%;transform:scaleX(0)}

/* cards */
.jr-card,.jr-big-card{background:#13151c;border-radius:10px;overflow:hidden;box-shadow:0 18px 50px rgba(20,22,31,.25)}
.jr-card-bar{display:flex;align-items:center;gap:6px;padding:9px 14px;color:#fff;font-size:12px;font-weight:700}
.jr-card-bar i{width:8px;height:8px;border-radius:50%;background:rgba(255,255,255,.55)}
.jr-card-bar span{margin-left:auto}
.jr-card pre,.jr-big-card pre{margin:0;padding:14px 14px 18px;font:12px/1.7 ui-monospace,Menlo,Consolas,monospace;color:#e6e6e6;white-space:pre}
.jr-card pre b,.jr-big-card pre b{display:inline-block;width:24px;color:#666;font-weight:400}
.jr-big-card{width:min(400px,100%);box-shadow:0 40px 90px rgba(20,22,31,.35),0 0 0 1px var(--c)}
.jr-big-card pre{font-size:14px;min-height:190px;padding:18px 18px 24px}
.jr-caret{display:inline-block;width:8px;height:15px;margin-left:2px;vertical-align:-2px;background:#fff;animation:jrBlink 1s steps(1) infinite}
@keyframes jrBlink{50%{opacity:0}}

/* hero */
.jr-hero{position:relative;z-index:1;min-height:100vh;padding:14vh 8vw 8vh}
.jr-hero .jr-small{position:absolute;right:4vw;top:calc(14vh + 6px);text-align:right}
.jr-hero h1{font-size:clamp(52px,9.6vw,150px);margin-left:calc(18vw + 24px)}
.jr-hero .ln{display:block;padding:.04em 0}
.jr-hero .ln i{display:block;font-style:normal}
.jr-hero .l1{font-size:.5em;margin-bottom:.45em;color:var(--mute);font-weight:700}
.jr-hero .l3{margin-left:.9em}
.jr-hero .l4{margin-left:.35em}
.jr-hero .jr-intro{margin:6vh 0 0 calc(18vw + 24px)}
.jr-hint{margin:22px 0 0 calc(18vw + 24px);font-size:13px;color:var(--mute)}
@media (prefers-reduced-motion:no-preference){
  .jr-hero .ln i{animation:jrUp .9s cubic-bezier(.2,.8,.2,1) both}
  .jr-hero .l2 i{animation-delay:.1s}.jr-hero .l3 i{animation-delay:.2s}.jr-hero .l4 i{animation-delay:.3s}
}
@keyframes jrUp{from{transform:translateY(40%);opacity:0}to{transform:none;opacity:1}}

/* particle portrait: left column me, hero ke top-left aur last section ke bottom-left (text ke peeche, mouse events text tak pahunchte hain) */
.jr-portrait{position:absolute;left:1vw;width:24vw;z-index:-1;pointer-events:none}
.jr-portrait.top{top:9vh;bottom:0}      /* hero me: nav ke neeche se shuru, marquee line par khadi */
.jr-portrait.bottom{top:12vh;bottom:0}  /* last section me: page ke bottom-left corner par khadi */
.jr-portrait canvas{display:block;width:100%;height:100%}

/* marquee */
.jr-marquee{position:relative;z-index:1;overflow:hidden;border-block:1px solid var(--ink);background:transparent}
.jr-marquee div{display:flex;width:max-content;animation:jrRun 38s linear infinite}
.jr-marquee span{padding:14px 28px;font-family:"Bricolage Grotesque",Arial,sans-serif;font-size:clamp(28px,4vw,56px);font-weight:800;letter-spacing:-.04em;
  color:transparent;-webkit-text-stroke:1px var(--ink);white-space:nowrap}
@keyframes jrRun{to{transform:translateX(-50%)}}
@media (prefers-reduced-motion:reduce){.jr-marquee div{animation:none}}

/* path: table left, picture right */
.jr-path{position:relative;z-index:1;display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr);gap:4vw;padding:16vh 8vw 14vh}
.jr-table-wrap h2{font-size:clamp(40px,6vw,92px);margin-bottom:8vh}
.jr-row{display:grid;grid-template-columns:40px 1fr 90px 78px;gap:14px;align-items:baseline;padding:16px 8px;font-size:13px}
.jr-head{color:var(--mute);border-bottom:1px solid var(--ink);padding:8px}
.jr-item{border-bottom:1px solid var(--line);cursor:pointer;outline-offset:-2px;transition:background .25s,color .25s}
.jr-item.on{background:var(--ink);color:#fff;border-bottom-color:var(--ink)}
.jr-tech{font-family:"Bricolage Grotesque",Arial,sans-serif;font-size:clamp(22px,2.6vw,38px);font-weight:800;letter-spacing:-.04em;line-height:1;transition:transform .35s cubic-bezier(.2,.8,.2,1)}
.jr-item.on .jr-tech{transform:translateX(14px)}
.jr-chip{justify-self:end;border:1px solid currentColor;border-radius:99px;padding:2px 10px;font-weight:700;opacity:.55}
.jr-chip.done{opacity:1;color:var(--accent)}
.jr-item.on .jr-chip.done{color:#9fa0ff}
.jr-more{display:grid;grid-template-rows:0fr;transition:grid-template-rows .4s cubic-bezier(.2,.8,.2,1)}
.jr-more>div{overflow:hidden}
.jr-item.on .jr-more{grid-template-rows:1fr}
.jr-more p{margin:0;padding:0 8px 22px 62px;font-size:15px;line-height:1.55;max-width:440px;color:#cfd2dd}
.jr-inline{display:none}

/* the picture on the right (static, no mouse effect) */
.jr-show{position:sticky;top:0;height:100vh;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:34px}
.jr-glow{position:absolute;width:70%;aspect-ratio:1;border-radius:50%;background:var(--c);filter:blur(90px);opacity:.25;z-index:0;
  animation:jrGlow .6s ease both}
@keyframes jrGlow{from{opacity:0;transform:scale(.6)}to{opacity:.25;transform:none}}
.jr-scene{position:relative;width:min(400px,100%);height:300px;z-index:1}
.jr-ghost{position:absolute;top:0;left:0;filter:blur(2.5px) grayscale(.4);opacity:.5}
.jr-ghost .jr-card{box-shadow:0 10px 30px rgba(20,22,31,.18)}
.g1{transform:translate(-60px,-70px) rotate(-6deg)}
.g2{transform:translate(70px,80px) rotate(5deg)}
.jr-front{position:relative}
@media (prefers-reduced-motion:no-preference){
  .jr-front{animation:jrSwap .5s cubic-bezier(.2,.8,.2,1) both}
  .jr-ghost{animation:jrGhost .7s cubic-bezier(.2,.8,.2,1) both}
  .jr-info{animation:jrFade .5s .15s both}
}
@keyframes jrSwap{from{opacity:0;filter:blur(8px);transform:translateY(30px) scale(.96)}to{opacity:1;filter:none;transform:none}}
@keyframes jrGhost{from{opacity:0}to{opacity:.5}}
@keyframes jrFade{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
.jr-info{position:relative;z-index:1;display:flex;flex-direction:column;align-items:center;gap:14px}
.jr-count{display:flex;align-items:baseline;gap:8px;font-size:13px;font-weight:700}
.jr-count b{font-family:"Bricolage Grotesque",Arial,sans-serif;font-size:clamp(36px,4.4vw,60px);letter-spacing:-.05em;line-height:1}
.jr-count span{color:var(--mute)}
.jr-tags{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;max-width:380px}
.jr-tags span{font-size:12px;font-weight:700;border:1px solid var(--ink);border-radius:99px;padding:4px 12px;background:var(--paper)}

/* last */
.jr-last{position:relative;z-index:1;min-height:90vh;padding:18vh 8vw 10vh}
.jr-last h2{font-size:clamp(40px,7vw,110px);margin-left:calc(18vw + 24px)}
.jr-last .jr-intro{margin:5vh 0 0 calc(18vw + 24px)}

/* mobile: picture opens inside the row instead */
@media (max-width:1080px){
  /* tablet: compact padding taaki table + sticky scene cramped na lage */
  .jr-hero,.jr-last{padding-left:6vw;padding-right:6vw}
  .jr-path{padding-left:6vw;padding-right:6vw;gap:3vw}
}
@media (max-width:860px){
  .jr-rule{left:14px}
  .jr-hero,.jr-last{padding-left:30px;padding-right:18px}
  .jr-hero .jr-small{position:static;margin-bottom:24px;width:auto;text-align:left}
  .jr-hero h1,.jr-last h2,.jr-hero .jr-intro,.jr-last .jr-intro,.jr-hint{margin-left:0}
  .jr-hero h1{font-size:clamp(36px,10.5vw,92px)}
  .jr-table-wrap h2{font-size:clamp(30px,8.5vw,64px);margin-bottom:5vh}
  .jr-last h2{font-size:clamp(30px,9vw,72px)}
  .jr-portrait,.jr-portrait.top,.jr-portrait.bottom{position:relative;top:auto;bottom:auto;left:auto;z-index:auto;max-width:none;width:min(62vw,260px);height:42vh;margin:0 auto 20px 0}
  .jr-portrait.bottom{margin:28px auto 0 0}
  .jr-path{grid-template-columns:1fr;padding:12vh 18px}
  .jr-show{display:none}
  .jr-row{grid-template-columns:30px 1fr 70px}
  .jr-row span:nth-child(3){display:none}
  .jr-more p{padding-left:38px}
  .jr-inline{display:block;padding:0 8px 22px 38px}
}
`;